{
  "findings": [
    {
      "check_id": "CKV_GCP_17",
      "title": "Kubernetes alpha features enabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "The cluster explicitly enables unstable Kubernetes alpha features, which may introduce unsupported or insufficiently tested functionality into the control plane."
    },
    {
      "check_id": "CKV_GCP_7",
      "title": "Legacy ABAC authorization enabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "HIGH",
      "explanation": "Legacy ABAC is explicitly enabled and can bypass the more granular Kubernetes RBAC authorization model, increasing the risk of excessive cluster permissions."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Kubernetes basic authentication enabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "HIGH",
      "explanation": "The control plane is configured with a static username and password. These long-lived credentials may be exposed through Terraform state or credential reuse and lack the protections of token-based authentication."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Client certificate issuance enabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "HIGH",
      "explanation": "The cluster issues a client certificate that can provide long-lived control-plane access if its private key is exposed."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Overly broad Compute Engine OAuth scope",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "Cluster nodes receive the full Compute Engine OAuth scope, allowing node credentials to invoke Compute APIs up to the permissions granted to the node service account."
    }
  ],
  "patched_code": "resource \"google_container_cluster\" \"k8sexample\" {\n  name                      = \"${var.vault_user}-k8s-cluster\"\n  description               = \"example k8s cluster\"\n  zone                      = \"${var.gcp_zone}\"\n  initial_node_count        = \"${var.initial_node_count}\"\n  enable_kubernetes_alpha   = false\n  enable_legacy_abac        = false\n\n  master_auth {\n    username = \"\"\n    password = \"\"\n\n    client_certificate_config {\n      issue_client_certificate = false\n    }\n  }\n\n  node_config {\n    machine_type = \"${var.node_machine_type}\"\n    disk_size_gb = \"${var.node_disk_size}\"\n    oauth_scopes = [\n      \"https://www.googleapis.com/auth/devstorage.read_only\",\n      \"https://www.googleapis.com/auth/logging.write\",\n      \"https://www.googleapis.com/auth/monitoring\"\n    ]\n  }\n}\n",
  "fix_summary": "Disabled Kubernetes alpha features, legacy ABAC, basic authentication, and client certificate issuance. Removed the broad Compute Engine OAuth scope while retaining the existing storage, logging, and monitoring scopes."
}
